import { ERRORS, number } from '../';

const validNumbers = [
  null,
  0,
  4,
  -1,
  -1.1,
  25.32,
  -25.32,
  '',
  '1',
  '-1',
  '1.1',
  '-1.1',
  '1.',
  '123',
  '123.123',
  '0',
  '01.01',
  '-0',
  '0.',
  '-123456789',
  '.123456789',
  '-.123456789',
  '-123456789.12345789',
  '25.32',
  '64',
  '-25.32',
];

const invalidNumbers = [
  false,
  [],
  'a',
  '-a',
  'a.a',
  '-a.a',
  '1a',
  'a1',
  'abc',
  '2tr5.i32',
  '-1a',
  '--1',
  '1..1',
  '..',
  'a-',
  'a.-',
  '--5-3-.-2-7-',
];

describe('number validator', () => {
  validNumbers.forEach((value) => {
    it(`'${value}' passes`, () => {
      expect(
        number({
          errors: [],
          value,
        }),
      ).toEqual([]);
    });
  });

  invalidNumbers.forEach((value) => {
    it(`'${value}' fails`, () => {
      expect(
        number({
          errors: [],
          value,
        }),
      ).toEqual([ERRORS.invalidNumber]);
    });
  });
});
